// Approval requests for a VM maintenance plan (output of Demo 5, or a fictional sample of two VMs).
// One request per task. Rules: the approver is the role from the task definition, the requester may never approve their own request (four-eyes), a request is valid for 48 h (urgent) or 7 days (planned).
const b = ($input.first().json || {}).body;
const sample = [
  { vm: 'sap-prd-app01', status: 'red', tasks: [{ vm: 'sap-prd-app01', key: 'patch', title: 'Install security patch', approver: 'Change board', reboot: true, urgency: 'urgent', because: 'Security patch missing for 34 days' }] },
  { vm: 'proxy-edge-01', status: 'red', tasks: [{ vm: 'proxy-edge-01', key: 'cert', title: 'Renew TLS certificate', approver: 'Security', reboot: false, urgency: 'urgent', because: 'TLS certificate expires in 5 days' }, { vm: 'proxy-edge-01', key: 'backup', title: 'Catch up the backup', approver: 'Backup owner', reboot: false, urgency: 'planned', because: 'Last backup 30 h ago' }] }
];
const live = b && Array.isArray(b.plan) && b.plan.length > 0;
const plan = live ? b.plan : sample;
const requester = String((live && b.requester) || 'maintenance-planner').slice(0, 60);
const now = Date.parse((live && b.now) || '2026-10-24T09:00:00Z');
const requests = plan.flatMap((p) => (p.tasks || []).map((t, i) => ({
  id: `AP-${String(t.vm).replace(/[^A-Za-z0-9]+/g, '-')}-${t.key}`.slice(0, 60),
  vm: String(t.vm), task: String(t.key), title: String(t.title), approver: String(t.approver), urgency: t.urgency === 'urgent' ? 'urgent' : 'planned',
  reboot: t.reboot === true, because: String(t.because || '').slice(0, 200), requester,
  expiresAt: new Date(now + (t.urgency === 'urgent' ? 2 : 7) * 864e5).toISOString(), status: 'pending'
})));
// Demo only: fictional decisions so the manual start shows every outcome. A real call waits for the people.
const sampleDecisions = live ? null : [
  { id: 'AP-sap-prd-app01-patch', decision: 'approved', by: 'c.weber', role: 'Change board', comment: 'Window Saturday 22:00' },
  { id: 'AP-proxy-edge-01-cert', decision: 'approved', by: 'maintenance-planner', role: 'Security', comment: 'Self-approval must not count' },
  { id: 'AP-proxy-edge-01-backup', decision: 'rejected', by: 'm.klein', role: 'Backup owner', comment: 'Run after the cert change' }
];
return [{ json: { demo: !live, now: new Date(now).toISOString(), requester, requests, sampleDecisions } }];

// Check every decision against the rules. Nothing is trusted: wrong role, self-approval, unknown request, late answer -> the request stays open or is marked invalid.
const planned = $('Plan and requests').first().json;
const input = $input.first().json;
const decisions = (planned.demo ? planned.sampleDecisions : (input.body && input.body.decisions)) || [];
const now = Date.parse(planned.now);
const out = planned.requests.map((r) => {
  const d = decisions.find((x) => x && x.id === r.id);
  const log = [`${r.id}: requested by ${r.requester}, approver role ${r.approver}`];
  let status = 'pending', reason = 'no answer yet';
  if (d) {
    if (d.role !== r.approver) { status = 'invalid'; reason = `role ${d.role} is not the approver (${r.approver})`; }
    else if (d.by === r.requester) { status = 'invalid'; reason = 'four-eyes rule: the requester cannot approve their own request'; }
    else if (d.decision === 'approved') { status = 'approved'; reason = d.comment || 'approved'; }
    else if (d.decision === 'rejected') { status = 'rejected'; reason = d.comment || 'rejected'; }
    else { status = 'invalid'; reason = 'decision must be approved or rejected'; }
    log.push(`decision by ${String(d.by).slice(0, 40)} (${d.role}): ${status} - ${reason}`);
  }
  if (status === 'pending' && now > Date.parse(r.expiresAt)) { status = 'expired'; reason = 'no answer within the time limit'; log.push('expired'); }
  return { json: { ...r, status, reason, log, go: status === 'approved' } };
});
return out;

// Approved tasks become the call for Demo 6 (operator runbook). Nothing is started here: the calls are prepared, one per task.
const items = $input.all().map((i) => i.json).filter((r) => r.go);
const calls = items.map((r, n) => ({
  ticket: { id: `T-AP-${n + 1}`, title: `${r.title} on ${r.vm}` },
  vm: r.vm, task: r.task, approved: true, approvedBy: r.reason, window: r.reboot ? 'Maintenance window needed (restart)' : 'Can run during operations'
}));
return [{ json: { released: calls, runbookWebhook: '/webhook/vm-operator-runbook', note: calls.length ? undefined : 'No approved task. Nothing is released.' } }];

// Approval report with audit trail. Open requests are reminded or escalated by a person, never approved automatically.
const reqs = $('Evaluate decisions').all().map((i) => i.json);
const rel = $input.first().json;
const count = (s) => reqs.filter((r) => r.status === s).length;
const counts = { requests: reqs.length, approved: count('approved'), rejected: count('rejected'), pending: count('pending'), invalid: count('invalid'), expired: count('expired') };
const lines = reqs.flatMap((r) => [`${r.id} [${r.urgency}] ${r.title} on ${r.vm}: ${r.status.toUpperCase()} (${r.reason})`, ...r.log.map((l) => `    ${l}`)]);
const todo = reqs.filter((r) => r.status === 'pending' || r.status === 'invalid' || r.status === 'expired').map((r) => `${r.id}: ask ${r.approver} again${r.urgency === 'urgent' ? ' (urgent, escalate to the on-call manager)' : ''}`);
const digest = [`VM maintenance approval: ${counts.requests} requests, ${counts.approved} approved, ${counts.rejected} rejected, ${counts.pending + counts.invalid + counts.expired} open`, ...lines, ...(todo.length ? ['Open:', ...todo] : []), `Released to the runbook: ${rel.released.length}. Nothing was run by this workflow.`].join('\n');
return [{ json: { counts, requests: reqs.map(({ go, ...r }) => r), released: rel.released, digest } }];
